{
  "name": "opencode-notify-me",
  "version": "1.0.1",
  "description": "Sound and toast notifications for OpenCode — know when the AI needs you",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "require": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "test": "jest",
    "test:watch": "jest --watch",
    "prepublishOnly": "npm run build && npm test"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "notifications",
    "sound",
    "toast",
    "cli",
    "ai"
  ],
  "author": "Lucas Malizia",
  "license": "MIT",
  "engines": {
    "node": ">=18.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@types/jest": "^29.5.14",
    "@types/node": "^25.6.2",
    "jest": "^29.7.0",
    "ts-jest": "^29.4.9",
    "typescript": "^5.9.3"
  },
  "files": [
    "dist",
    "sounds",
    "README.md",
    "LICENSE"
  ],
  "homepage": "https://github.com/0xlukem/opencode-alert#readme",
  "repository": {
    "type": "git",
    "url": "https://github.com/0xlukem/opencode-alert.git"
  }
}
